2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import { open, stat } from 'node:fs/promises';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const STDIN = '-';
10	
11	class CliError extends Error {
12	  constructor(message, exitCode) {
13	    super(message);
14	    this.exitCode = exitCode;
15	  }
16	}
17	
18	function readError(name, reason) {
19	  return new CliError(`Error: ${name}: ${reason}`, 1);
20	}
21	
22	// Collects chunks from an async iterable, stopping once the byte limit is passed.
23	async function collect(chunks, name) {
24	  const parts = [];
25	  let total = 0;
26	  for await (const chunk of chunks) {
27	    total += chunk.length;
28	    if (total > MAX_BYTES) throw readError(name, 'too large');
29	    parts.push(chunk);
30	  }
31	  return Buffer.concat(parts, total);
32	}
33	
34	async function* fileChunks(handle) {
35	  const buffer = Buffer.alloc(65536);
36	  for (;;) {
37	    const { bytesRead } = await handle.read(buffer, 0, buffer.length, null);
38	    if (bytesRead === 0) return;
39	    yield Buffer.from(buffer.subarray(0, bytesRead));
40	  }
41	}
42	
43	async function isDirectory(path) {
44	  try {
45	    return (await stat(path)).isDirectory();
46	  } catch {
47	    return false;
48	  }
49	}
50	
51	async function readFile(path) {
52	  let handle;
53	  try {
54	    handle = await open(path, 'r');
55	  } catch (err) {
56	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
57	    if (err.code === 'EISDIR' || (await isDirectory(path))) throw readError(path, 'is a directory');
58	    throw readError(path, 'cannot read');
59	  }
60	  try {
61	    if ((await handle.stat()).isDirectory()) throw readError(path, 'is a directory');
62	    return await collect(fileChunks(handle), path);
63	  } catch (err) {
64	    if (err instanceof CliError) throw err;
65	    throw readError(path, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
66	  } finally {
67	    await handle.close().catch(() => {});
68	  }
69	}
70	
71	async function readStdin() {
72	  try {
73	    return await collect(process.stdin, 'stdin');
74	  } catch (err) {
75	    if (err instanceof CliError) throw err;
76	    throw readError('stdin', 'cannot read');
77	  } finally {
78	    process.stdin.destroy();
79	  }
80	}
81	
82	function depthExceeds(value, limit) {
83	  const stack = [[value, 0]];
84	  while (stack.length > 0) {
85	    const [current, depth] = stack.pop();
86	    if (current === null || typeof current !== 'object') continue;
87	    if (depth + 1 > limit) return true;
88	    for (const item of Object.values(current)) stack.push([item, depth + 1]);
89	  }
90	  return false;
91	}
92	
93	async function loadJson(arg) {
94	  const name = arg === STDIN ? 'stdin' : arg;
95	  const bytes = arg === STDIN ? await readStdin() : await readFile(arg);
96	  let text;
97	  try {
98	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
99	  } catch {
100	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
101	  }
102	  let value;
103	  try {
104	    value = JSON.parse(text);
105	  } catch {
106	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
107	  }
108	  if (depthExceeds(value, MAX_DEPTH)) throw new CliError(`Error: ${name}: too deep`, 3);
109	  return value;
110	}
111	
112	async function main(args) {
113	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
114	  const [patchArg, docArg = STDIN] = args;
115	  if (patchArg === STDIN && docArg === STDIN) throw new CliError(USAGE, 2);
116	  const patch = await loadJson(patchArg);
117	  const doc = await loadJson(docArg);
118	  let result;
119	  try {
120	    result = applyPatch(doc, patch);
121	  } catch (err) {
122	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
123	    throw err;
124	  }
125	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
126	}
127	
128	main(process.argv.slice(2)).catch((err) => {
129	  if (!(err instanceof CliError)) throw err;
130	  process.stderr.write(`${err.message}\n`);
131	  process.exitCode = err.exitCode;
132	});
